  switch (m[r'$']) {
    case null:
      return Uri(scheme: decString(m['scheme']), userInfo: decString(m['userInfo']), host: decString(m['host']), port: decInt(m['port']), path: decString(m['path']), pathSegments: fuseList<String>(m['pathSegments'], (e) => decString(e)!), query: decString(m['query']), queryParameters: fuseMap<String, dynamic>(m['queryParameters'], (k) => k, (e) => e), fragment: decString(m['fragment']));
    case 'http':
      return Uri.http(fuseReq(decString(m['authority']), 'Uri.http', 'authority'), decString(m['unencodedPath']) ?? '', fuseMap<String, dynamic>(m['queryParameters'], (k) => k, (e) => e));
    case 'https':
      return Uri.https(fuseReq(decString(m['authority']), 'Uri.https', 'authority'), decString(m['unencodedPath']) ?? '', fuseMap<String, dynamic>(m['queryParameters'], (k) => k, (e) => e));
    case 'file':
      return Uri.file(fuseReq(decString(m['path']), 'Uri.file', 'path'), windows: decBool(m['windows']));
    case 'directory':
      return Uri.directory(fuseReq(decString(m['path']), 'Uri.directory', 'path'), windows: decBool(m['windows']));
    case 'dataFromString':
      return Uri.dataFromString(fuseReq(decString(m['content']), 'Uri.dataFromString', 'content'), mimeType: decString(m['mimeType']), parameters: fuseMap<String, String>(m['parameters'], (k) => k, (e) => decString(e)!), base64: decBool(m['base64']) ?? false);
    case 'dataFromBytes':
      return Uri.dataFromBytes(fuseReq(fuseList<int>(m['bytes'], (e) => decInt(e)!), 'Uri.dataFromBytes', 'bytes'), mimeType: decString(m['mimeType']) ?? 'application/octet-stream', parameters: fuseMap<String, String>(m['parameters'], (k) => k, (e) => decString(e)!), percentEncoded: decBool(m['percentEncoded']) ?? false);
  }
  return fuseBad('Uri', v);
}

